import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;
// 가정: balance는 차변(+)·대변(-) 누적, 조회 시작일 이전 거래를 포함한 거래처·계정별 잔액이다.
// 가정: periodTotal은 조회 기간 안에서 같은 거래처·계정의 일(또는 월) 단위 차변-대변 합계이다.
// 가정: 승인해제 전표는 장부에서 제외한다.

function textOf(v: unknown): string {
  return typeof v === 'string' ? v.trim() : '';
}

function idOf(v: unknown): string | null {
  const t = textOf(v);
  if (t === '') {
    return null;
  }
  if (!/^\d+$/.test(t)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '거래처·계정과목 값이 올바르지 않습니다.');
  }
  return t;
}

@Controller('api/v1')
export class FnSfr00806Controller {
  @Get('/partner-ledgers')
  async listPartnerLedgers(@Req() req: Request) {
    const user = currentUser(req);
    user.require('예산·회계 담당자', '임직원');
    const query = checks.queryOf(req.query);
    const dateFrom = textOf(query['dateFrom']);
    const dateTo = textOf(query['dateTo']);
    if (dateFrom === '' || dateTo === '') {
      throw new ApiError(400, 'VALIDATION_FAILED', '조회 시작일과 종료일을 입력하세요.');
    }
    if (!DATE_PATTERN.test(dateFrom) || !DATE_PATTERN.test(dateTo)) {
      throw new ApiError(422, 'INVALID_PERIOD', '조회 기간이 올바르지 않습니다.');
    }
    const partnerId = idOf(query['partnerId']);
    const accountItemId = idOf(query['accountItemId']);
    const unitText = textOf(query['aggregationUnit']);
    const unit = unitText === '' ? '일별' : unitText;
    if (unit !== '일별' && unit !== '월별') {
      throw new ApiError(422, 'INVALID_AGGREGATION_UNIT', '집계 단위는 일별 또는 월별만 선택할 수 있습니다.');
    }
    const pageText = textOf(query['page']);
    const sizeText = textOf(query['size']);
    const page = pageText === '' ? 0 : Number(pageText);
    let size = sizeText === '' ? DEFAULT_SIZE : Number(sizeText);
    if (!Number.isInteger(page) || page < 0 || !Number.isInteger(size) || size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호나 크기가 올바르지 않습니다.');
    }
    if (size > MAX_SIZE) {
      size = MAX_SIZE;
    }
    return transaction(async (db) => {
      const bad = await db.query(
        'SELECT CAST(:dateFrom AS date) > CAST(:dateTo AS date) AS "invalid"',
        { dateFrom, dateTo },
      );
      if (bad[0] && bad[0]['invalid'] === true) {
        throw new ApiError(422, 'INVALID_PERIOD', '조회 시작일이 종료일보다 늦습니다.');
      }
      const params = { dateFrom, dateTo, partnerId, accountItemId, unit, limit: size, offset: page * size };
      const countRows = await db.query(
        `SELECT COUNT(*) AS "total"
         FROM voucher_line vl
         JOIN journal_voucher jv ON jv.journal_voucher_id = vl.journal_voucher_id
         JOIN partner p ON p.partner_id = vl.partner_id
         JOIN account_item a ON a.account_item_id = vl.account_item_id
         WHERE jv.status <> '승인해제'
           AND jv.voucher_date >= CAST(:dateFrom AS date)
           AND jv.voucher_date <= CAST(:dateTo AS date)
           AND (CAST(:partnerId AS bigint) IS NULL OR vl.partner_id = CAST(:partnerId AS bigint))
           AND (CAST(:accountItemId AS bigint) IS NULL OR vl.account_item_id = CAST(:accountItemId AS bigint))`,
        params,
      );
      const rows = await db.query(
        `SELECT t.partner_name AS "partnerName",
                t.account_name AS "accountName",
                t.voucher_date AS "voucherDate",
                t.dc_type AS "dcType",
                t.amount AS "amount",
                t.balance AS "balance",
                SUM(t.signed_amount) OVER (PARTITION BY t.partner_id, t.account_item_id, t.period_key) AS "periodTotal"
         FROM (
           SELECT p.partner_name, a.account_name, jv.voucher_date, vl.dc_type, vl.amount,
                  vl.voucher_line_id, vl.partner_id, vl.account_item_id,
                  CASE WHEN vl.dc_type = 'DEBIT' THEN vl.amount ELSE -vl.amount END AS signed_amount,
                  SUM(CASE WHEN vl.dc_type = 'DEBIT' THEN vl.amount ELSE -vl.amount END)
                    OVER (PARTITION BY vl.partner_id, vl.account_item_id ORDER BY jv.voucher_date, vl.voucher_line_id) AS balance,
                  CASE WHEN CAST(:unit AS text) = '월별'
                       THEN CAST(date_trunc('month', jv.voucher_date) AS date)
                       ELSE jv.voucher_date END AS period_key
           FROM voucher_line vl
           JOIN journal_voucher jv ON jv.journal_voucher_id = vl.journal_voucher_id
           JOIN partner p ON p.partner_id = vl.partner_id
           JOIN account_item a ON a.account_item_id = vl.account_item_id
           WHERE jv.status <> '승인해제'
             AND jv.voucher_date <= CAST(:dateTo AS date)
             AND (CAST(:partnerId AS bigint) IS NULL OR vl.partner_id = CAST(:partnerId AS bigint))
             AND (CAST(:accountItemId AS bigint) IS NULL OR vl.account_item_id = CAST(:accountItemId AS bigint))
         ) t
         WHERE t.voucher_date >= CAST(:dateFrom AS date)
         ORDER BY t.partner_name, t.account_name, t.voucher_date, t.voucher_line_id
         LIMIT :limit OFFSET :offset`,
        params,
      );
      const items = rows.map((r: Record<string, unknown>) => ({
        partnerName: r['partnerName'],
        accountName: r['accountName'],
        voucherDate: r['voucherDate'],
        dcType: r['dcType'],
        amount: Number(r['amount']),
        balance: Number(r['balance']),
        periodTotal: Number(r['periodTotal']),
      }));
      return {
        items,
        page,
        size,
        total: Number(countRows[0] ? countRows[0]['total'] : 0),
      };
    });
  }
}

