import { useState } from 'react';
import {
  Badge,
  Band,
  DataTable,
  DateInput,
  DateText,
  Drawer,
  ErrorText,
  Field,
  Filters,
  LookupSelect,
  Num,
  Pager,
  Pairs,
  Select,
  Tiles,
  call,
  useData,
} from '../kit';
import type { Page, PageProps, Row } from '../kit';

const EMPTY: Page = { items: [], page: 0, size: 20, total: 0 };

export default function FnSfr00806Page({ role, notify }: PageProps) {
  const [dateFrom, setDateFrom] = useState('');
  const [dateTo, setDateTo] = useState('');
  const [partnerId, setPartnerId] = useState<number | string>('');
  const [accountItemId, setAccountItemId] = useState<number | string>('');
  const [unit, setUnit] = useState('일별');
  const [applied, setApplied] = useState<Row | null>(null);
  const [page, setPage] = useState(0);
  const [message, setMessage] = useState('');
  const [selected, setSelected] = useState<Row | null>(null);

  const { data, error } = useData<Page>(async () => {
    if (!applied) {
      return EMPTY;
    }
    return call<Page>('GET', '/partner-ledgers', role, undefined, { ...applied, page, size: 20 });
  }, [applied, page, role]);

  const search = () => {
    if (dateFrom === '' || dateTo === '') {
      setMessage('조회 시작일과 종료일을 입력하세요.');
      return;
    }
    if (dateFrom > dateTo) {
      setMessage('조회 시작일이 종료일보다 늦습니다.');
      return;
    }
    setMessage('');
    setPage(0);
    setApplied({ dateFrom, dateTo, partnerId, accountItemId, aggregationUnit: unit });
    notify('조회했습니다.');
  };

  const reset = () => {
    setDateFrom('');
    setDateTo('');
    setPartnerId('');
    setAccountItemId('');
    setUnit('일별');
    setMessage('');
    setPage(0);
    setApplied(null);
  };

  const list = data ?? EMPTY;

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>조회 건수</h2>
        <Tiles items={[['장부 내역', <Num value={list.total} />]]} />
      </section>
      <section className="box span-8">
        <h2>조회 조건</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="조회 시작일" required>
            <DateInput value={dateFrom} onChange={setDateFrom} />
          </Field>
          <Field label="조회 종료일" required>
            <DateInput value={dateTo} onChange={setDateTo} />
          </Field>
          <Field label="거래처">
            <LookupSelect table="partner" role={role} value={partnerId} onChange={setPartnerId} />
          </Field>
          <Field label="계정과목">
            <LookupSelect table="account_item" role={role} value={accountItemId} onChange={setAccountItemId} />
          </Field>
          <Field label="집계 단위">
            <Select
              value={unit}
              onChange={setUnit}
              options={[
                ['일별', '일별'],
                ['월별', '월별'],
              ]}
            />
          </Field>
        </Filters>
        {message !== '' && <ErrorText text={message} />}
      </section>
      <section className="box span-12">
        <h2>거래처 원장</h2>
        <Band total={list.total} />
        {error !== '' && <ErrorText text={error} />}
        <DataTable
          columns={[
            { key: 'partnerName', label: '거래처 명칭' },
            { key: 'accountName', label: '계정과목 명칭' },
            { key: 'voucherDate', label: '전표일자', render: (r) => <DateText value={r.voucherDate} /> },
            { key: 'dcType', label: '차대 구분', render: (r) => <Badge value={r.dcType} /> },
            { key: 'amount', label: '금액', render: (r) => <Num value={r.amount} /> },
            { key: 'balance', label: '계정 잔액', render: (r) => <Num value={r.balance} /> },
            { key: 'periodTotal', label: '일·월별 집계 금액', render: (r) => <Num value={r.periodTotal} /> },
          ]}
          rows={list.items}
          onRowClick={(r) => setSelected(r)}
          empty="조회 기간과 조건을 지정하고 조회하세요."
        />
        <Pager page={list.page} size={list.size} total={list.total} onPage={setPage} />
      </section>
      {selected && (
        <Drawer title="장부 내역 상세" onClose={() => setSelected(null)}>
          <Pairs
            items={[
              ['거래처 명칭', String(selected.partnerName ?? '')],
              ['계정과목 명칭', String(selected.accountName ?? '')],
              ['전표일자', <DateText value={selected.voucherDate} />],
              ['차대 구분', <Badge value={selected.dcType} />],
              ['금액', <Num value={selected.amount} />],
              ['계정 잔액', <Num value={selected.balance} />],
              ['일·월별 집계 금액', <Num value={selected.periodTotal} />],
            ]}
          />
        </Drawer>
      )}
    </div>
  );
}
